"""Check the integration against schema generated by the installed Codex binary."""

import asyncio
import dataclasses
import json
import shutil
import subprocess
import tempfile
import unittest
from pathlib import Path

from test_agent import config

from slack_debug.codex import Codex


class InstalledProtocolTests(unittest.TestCase):
    @unittest.skipUnless(shutil.which("codex"), "Codex CLI not installed")
    def test_text_only_thread_disables_configured_tools_without_a_model_turn(self):
        async def probe():
            with tempfile.TemporaryDirectory() as directory:
                root = Path(directory)
                home = root / "codex-home"
                home.mkdir()
                (home / "config.toml").write_text(
                    '[mcp_servers.probe]\nurl="http://127.0.0.1:9/mcp"\n'
                )

                async def reject(method, params):
                    raise RuntimeError("Unexpected tool request")

                class Probe(Codex):
                    async def call(self, method, params):
                        result = await super().call(method, params)
                        if method == "thread/start":
                            self.start_params = params
                            self.started = result
                        return result

                client = Probe(dataclasses.replace(config(root), codex_home=home), reject)
                try:
                    await client.start("Draft an RCA from supplied evidence.", text_only=True)
                    self.assertEqual(client.started["approvalPolicy"], "never")
                    self.assertEqual(client.started["sandbox"]["type"], "readOnly")
                    self.assertFalse(client.started["sandbox"]["networkAccess"])
                    self.assertTrue(client.start_params["ephemeral"])
                    self.assertFalse(client.start_params["config"]["features"]["shell_tool"])
                    status = await client.call("mcpServerStatus/list", {"threadId": client.thread_id})
                    self.assertEqual(
                        [(entry["name"], entry["runtimeStatus"]) for entry in status["data"]],
                        [("probe", "disabled")],
                    )
                finally:
                    await client.close()

        asyncio.run(asyncio.wait_for(probe(), 20))

    @unittest.skipUnless(shutil.which("codex"), "Codex CLI not installed")
    def test_native_thread_survives_process_restart_without_model_execution(self):
        async def probe():
            with tempfile.TemporaryDirectory() as directory:
                root = Path(directory)
                home = root / "codex-home"
                home.mkdir()
                (home / "config.toml").write_text('model="profile-marker"\n')
                settings = dataclasses.replace(config(root), codex_home=home)

                async def reject(method, params):
                    raise RuntimeError("This test must not run tools")

                first = Codex(settings, reject)
                try:
                    await first.start("Persistence test; do not run tools.")
                    thread = first.thread_id
                    # Seed synthetic history without a model turn or network request.
                    await first.call("thread/inject_items", {"threadId": thread, "items": [{
                        "type": "message", "role": "user", "content": [{
                            "type": "input_text", "text": "Saved persistence marker",
                        }],
                    }]})
                finally:
                    await first.close()
                self.assertTrue(any("Saved persistence marker" in path.read_text()
                                    for path in home.rglob("*.jsonl")))
                second = Codex(settings, reject)
                original_call = second.call
                results = []

                async def record(method, params):
                    result = await original_call(method, params)
                    if method == "thread/resume":
                        results.append(result)
                    return result

                second.call = record
                try:
                    await second.start("Persistence test; do not run tools.", resume_thread=thread)
                    self.assertEqual(second.thread_id, thread)
                    self.assertEqual(results[0]["approvalPolicy"], "on-request")
                    self.assertEqual(results[0]["sandbox"]["type"], "workspaceWrite")
                    self.assertFalse(results[0]["sandbox"]["networkAccess"])
                    self.assertEqual(results[0]["sandbox"]["writableRoots"], [])
                finally:
                    await second.close()

        asyncio.run(probe())

    @unittest.skipUnless(shutil.which("codex"), "Codex CLI not installed")
    def test_native_profile_overrides_and_sandbox_without_a_model_turn(self):
        async def probe():
            with tempfile.TemporaryDirectory() as directory:
                root = Path(directory)
                home = root / "codex-home"
                home.mkdir()
                (home / "config.toml").write_text('model="base-marker"\n')
                settings = dataclasses.replace(
                    config(root),
                    codex_home=home,
                    profile_name="diagnose",
                    profile_config={
                        "model": "profile-marker",
                        "model_reasoning_effort": "high",
                        "approval_policy": "never",
                        "sandbox_mode": "danger-full-access",
                        "sandbox_workspace_write": {
                            "network_access": True,
                            "writable_roots": ["/"],
                        },
                    },
                )

                async def reject(method, params):
                    raise RuntimeError("This test must not request any tool execution")

                client = Codex(settings, reject)
                original_call = client.call
                results = []

                async def record(method, params):
                    result = await original_call(method, params)
                    if method == "thread/start":
                        results.append(result)
                    return result

                client.call = record
                try:
                    await asyncio.wait_for(
                        client.start("Protocol configuration test; do not run tools."), 20
                    )
                    result = results[0]
                    self.assertEqual(result["model"], "profile-marker")
                    self.assertEqual(result["reasoningEffort"], "high")
                    self.assertEqual(result["approvalPolicy"], "on-request")
                    self.assertEqual(result["sandbox"]["type"], "workspaceWrite")
                    self.assertFalse(result["sandbox"]["networkAccess"])
                    self.assertEqual(result["sandbox"]["writableRoots"], [])
                    self.assertTrue(result["sandbox"]["excludeTmpdirEnvVar"])
                    self.assertTrue(result["sandbox"]["excludeSlashTmp"])
                finally:
                    await client.close()

        asyncio.run(probe())

    @unittest.skipUnless(shutil.which("codex"), "Codex CLI not installed")
    def test_installed_schema_contract(self):
        with tempfile.TemporaryDirectory() as directory:
            subprocess.run(
                ["codex", "app-server", "generate-json-schema", "--out", directory],
                capture_output=True,
                check=True,
            )
            root = Path(directory)
            elicitation = json.loads((root / "McpServerElicitationRequestParams.json").read_text())
            self.assertTrue({"serverName", "threadId"} <= elicitation["properties"].keys())
            modes = {mode for variant in elicitation["oneOf"]
                     for mode in variant["properties"]["mode"]["enum"]}
            self.assertEqual(modes, {"form", "openai/form", "openaiForm", "url"})
            response = json.loads((root / "McpServerElicitationRequestResponse.json").read_text())
            self.assertEqual(set(response["definitions"]["McpServerElicitationAction"]["enum"]),
                             {"accept", "decline", "cancel"})
            self.assertIn("content", response["properties"])
            completed = json.loads((root / "v2/ItemCompletedNotification.json").read_text())
            definitions = completed["definitions"]
            items = {option["properties"]["type"]["enum"][0]: option["properties"]
                     for option in definitions["ThreadItem"]["oneOf"]}
            for kind, fields in {
                "commandExecution": {"command", "commandActions", "exitCode"},
                "agentMessage": {"text", "phase"},
                "fileChange": {"changes"},
                "mcpToolCall": {"server", "tool"},
            }.items():
                self.assertTrue(fields <= items[kind].keys())
            actions = {option["properties"]["type"]["enum"][0]: option["properties"]
                       for option in definitions["CommandAction"]["oneOf"]}
            self.assertTrue({"name", "path"} <= actions["read"].keys())
            self.assertIn("query", actions["search"])
            self.assertIn("path", actions["listFiles"])
            for name, definition in (
                ("CommandExecution", "CommandExecutionApprovalDecision"),
                ("FileChange", "FileChangeApprovalDecision"),
            ):
                response = json.loads((root / f"{name}RequestApprovalResponse.json").read_text())
                values = {
                    v
                    for option in response["definitions"][definition]["oneOf"]
                    for v in option.get("enum", [])
                }
                self.assertTrue({"accept", "decline"} <= values)
            start = json.loads((root / "v2/ThreadStartParams.json").read_text())
            self.assertTrue(
                {
                    "developerInstructions",
                    "ephemeral",
                    "approvalPolicy",
                    "approvalsReviewer",
                    "sandbox",
                }
                <= start["properties"].keys()
            )
            turn = json.loads((root / "v2/TurnStartParams.json").read_text())
            self.assertTrue({"threadId", "input"} <= turn["properties"].keys())
            resume = json.loads((root / "v2/ThreadResumeParams.json").read_text())
            self.assertTrue({"threadId", "developerInstructions", "config", "sandbox",
                             "approvalPolicy", "approvalsReviewer", "excludeTurns"}
                            <= resume["properties"].keys())


if __name__ == "__main__":
    unittest.main()
